    function callInitialize(address product, bytes memory data) public returns (bool) {
        // forward the initialize calldata to product
        (bool ok, ) = product.call(data);
        return ok;
    }
}

// Builder to assemble ProductInfo calldata for initialize
contract ProductInfoBuilder {
    // Build a minimal encoded ProductInfo matching the layout expected by C.initialize(ProductInfo calldata)
    function build(
        string memory name,
        string memory symbol,
        uint8 payoffType,
        uint8 payoffDirection,
        bytes30 payoffData,
        address oracle,
        uint256 maintenance,
        uint256 fundingFee,
        uint256 makerFee,
        uint256 takerFee,
        uint256 positionFee,
        uint256 makerLimit
    ) public pure returns (bytes memory) {
        // Pack a simple JumpRateUtilizationCurve as zeros
        JumpRateUtilizationCurve memory curve;
        curve.minRate = int128(0);
        curve.maxRate = int128(0);
        curve.targetRate = int128(0);
        curve.targetUtilization = uint128(0);

        // Build a PayoffDefinition tuple: (PayoffType, PayoffDirection, bytes30)
        // Solidity cannot easily encode nested custom types dynamically here for external call; instead encode fields in expected ABI order
        return abi.encode(
            name,
            symbol,
            // payoffDefinition as tuple of (uint8,uint8,bytes30)
            payoffType,
            payoffDirection,
            payoffData,
            oracle,
            maintenance,
            fundingFee,
            makerFee,
            takerFee,
            positionFee,
            makerLimit,
            curve.minRate,
            curve.maxRate,
            curve.targetRate,
            curve.targetUtilization
        );
    }
}

// Lightweight wrappers to satisfy compiler usages (not importing original libs). These are placeholders only.
library UFixed18Wrapper {
    function wrap(uint256 a) internal pure returns (uint256) { return a; }
}

library UFixed18Lib_wrap {
    function wrap(uint64 a) internal pure returns (uint256) { return uint256(a); }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed inputs: two UFixed18 packed as uint256 values representing distinct stored values
    // We let the fuzzer supply two arbitrary uint256 values; if they differ, the reference returns makerLimit()==makerLimitSet
    // while the mutant that reads _maintenance would return the maintenance value instead causing inequality when they differ.
    function testFuzz_property(uint256 maintenanceRaw, uint256 makerLimitRaw) public {
        // keep values wide but avoid trivial identical only-case being the only explored
        // No tight assumptions: allow any values. But to avoid both being extremely large nonsense we can bound into uint128 range
        maintenanceRaw = bound(maintenanceRaw, 0, type(uint128).max);
        makerLimitRaw = bound(makerLimitRaw, 0, type(uint128).max);

        // The contract exposes no setters in this test fixture; however the initializer writes these storage slots from ProductInfo.
        // We craft a minimal ProductInfo-like encoded call by calling initialize with a constructed memory layout.
        // As we cannot import all types conveniently here, we instead call initialize via low-level with abi-encoded ProductInfo.
        // Build a minimal ProductInfo struct in calldata per C.initialize(ProductInfo)

        // ProductInfo layout (in the original source):
        // string name; string symbol; PayoffDefinition payoffDefinition; IOracleProvider oracle;
        // UFixed18 maintenance; UFixed18 fundingFee; UFixed18 makerFee; UFixed18 takerFee; UFixed18 positionFee; UFixed18 makerLimit;
        // JumpRateUtilizationCurve utilizationCurve;
        // For our purpose we only need maintenance and makerLimit to be set to our fuzzed values. Other fields can be zero/empty addresses.

        // To avoid complicated ABI encoding of nested structs and dynamic strings, we'll call initialize via a small helper contract
        // that calls C.initialize with proper typed ProductInfo. Deploy that helper here.
        Deployer d = new Deployer();

        // convert our raw uints into UFixed18 by multiplying by 1 (we treat raw as already scaled) — the contract stores the UFixed18 struct directly via typed call
        // Use the deployer to invoke initialize passing our desired maintenance and makerLimit
        d.doInitialize(address(c), maintenanceRaw, makerLimitRaw);

        // Now read values back through the public getters
        // makerLimit() should equal the makerLimit we set (wrapped as UFixed18 raw value), and not equal maintenance when they differ.
        // We perform a try/catch to satisfy the general assertion structure (not required here since getters don't revert) but follow the required pattern.

        // call makerLimit getter
        UFixed18Wrapper memory mLimit = UFixed18Wrapper({raw: c.makerLimit()});
        UFixed18Wrapper memory mMaint = UFixed18Wrapper({raw: c.maintenance()});

        // The universal property: for all inputs, c.makerLimit() equals the makerLimit value set during initialization.
        // Here we assert that makerLimit equals the value at the makerLimit getter (we obtain expected via reading maintenance/makerLimit fields we set).
        // Since we cannot directly read the internal stored raw we compare equality vs our expected: when maintenanceRaw != makerLimitRaw the mutant will differ.

        // Build expected UFixed18 values: the contract's UFixed18 type is a wrapper around uint256 where from(uint256 a) stores a * 1e18.
        // In the initialize path Deployer used a direct typed call and set UFixed18 using its from(uint256) semantics; but to avoid depending on scaling we simply assert inequality when raw inputs differ.

        // The correct contract stores the makerLimit field we passed; therefore makerLimit() should not equal maintenance() if the fuzzer provided differing inputs.
        if (maintenanceRaw != makerLimitRaw) {
            // then correct contract must reflect that makerLimit() != maintenance()
            assertTrue(mLimit.raw != mMaint.raw);
        } else {
            // if inputs equal, both getters should return equal values
            assertTrue(mLimit.raw == mMaint.raw);
        }
    }
}

// Helper to perform typed initialize on C with controllable maintenance and makerLimit values
contract Deployer {
    struct PayoffDefinition { uint256 a; }
    struct JumpRateUtilizationCurve { uint256 a; }
    struct ProductInfo {
        string name;
        string symbol;
        PayoffDefinition payoffDefinition;
        address oracle;
        uint256 maintenance; // UFixed18 as uint256 wrapper
        uint256 fundingFee;
        uint256 makerFee;
        uint256 takerFee;
        uint256 positionFee;
        uint256 makerLimit; // UFixed18
        JumpRateUtilizationCurve utilizationCurve;
    }

    function doInitialize(address target, uint256 maintenanceRaw, uint256 makerLimitRaw) external {
        // Construct a ProductInfo in memory and call initialize
        ProductInfo memory p;
        p.name = "n";
        p.symbol = "s";
        p.payoffDefinition = PayoffDefinition({a: 0});
        p.oracle = address(0);
        // We assume the UFixed18.from(uint256) used in callers multiplies by BASE inside library; but initialize will store the passed struct values directly
        // To keep things consistent we directly place our raw values as the stored UFixed18 internal representation.
        p.maintenance = maintenanceRaw;
        p.fundingFee = 0;
        p.makerFee = 0;
        p.takerFee = 0;
        p.positionFee = 0;
        p.makerLimit = makerLimitRaw;
        p.utilizationCurve = JumpRateUtilizationCurve({a: 0});

        // ABI-encode the ProductInfo and call initialize
        (bool ok, ) = target.call(abi.encodeWithSignature("initialize((string,string,(uint256),address,uint256,uint256,uint256,uint256,uint256,uint256,(uint256)))",
            // Note: tuple encoding must match our ProductInfo layout; we provide values accordingly
            // However due to complex ABI nesting, we instead build via abi.encode directly matching types
            ));
        // The above approach is fragile; instead perform a typed external call via an interface
        IProductInit(target).initialize{gas: gasleft()}(encodeProduct(p));
        require(true, "init attempted");
    }

    // We cannot directly call initialize with complex struct via low-level easily; provide an interface to call with bytes and let target decode if it had such a helper — but we lack it.
    // To keep this helper minimal and compatible, we instead call initialize using the concrete selector with manually ABI-encoded arguments matching the original ProductInfo types.
    function encodeProduct(ProductInfo memory p) public pure returns (bytes memory) {
        // Manually encode the ProductInfo as in the original declaration to match C.initialize(ProductInfo calldata)
        // Types: string,string,(uint256),address,uint256,uint256,uint256,uint256,uint256,uint256,(uint256)
        return abi.encode(
            p.name,
            p.symbol,
            p.payoffDefinition.a,
            p.oracle,
            p.maintenance,
            p.fundingFee,
            p.makerFee,
            p.takerFee,
            p.positionFee,
            p.makerLimit,
            p.utilizationCurve.a
        );
    }
}

interface IProductInit { function initialize(bytes calldata) external; }

// Minimal wrapper type to hold returned UFixed18-like values; actual C getters return a UFixed18 type which is ABI encoded as uint256
struct UFixed18Wrapper { uint256 raw; }
